-- Упражнения книги 17, глава 23 (oVirt). Файл строит scratchpad/ovirt/builder.py; после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-split-href', 0, 'func', 'Разбор ссылки REST', 'Ссылки в ответах REST API выглядят как "/ovirt-engine/api/vms/123/nics/9". После префикса "/ovirt-engine/api" идут сегменты, которые чередуются: имя коллекции, идентификатор, имя коллекции, идентификатор и так далее. Напишите функцию split_href(href): верните список кортежей (коллекция, идентификатор). Если на конце имя без идентификатора (коллекция или действие), в последнем кортеже идентификатор равен None. Префикс может отсутствовать (тогда это просто путь), пустые сегменты из-за лишних слэшей игнорируйте. Префикс убирается только если href равен ему или начинается с него и слэша.', 'def split_href(href):
    pass
', 'Уберите префикс, разбейте по ''/'', отфильтруйте пустые и идите по парам с шагом 2.', '{"func": "split_href", "tests": [{"args": ["/ovirt-engine/api/vms/123/nics"], "expected": [{"__tuple__": ["vms", "123"]}, {"__tuple__": ["nics", null]}]}, {"args": ["/ovirt-engine/api/vms/123/nics/9"], "expected": [{"__tuple__": ["vms", "123"]}, {"__tuple__": ["nics", "9"]}]}, {"args": ["/ovirt-engine/api/vms"], "expected": [{"__tuple__": ["vms", null]}]}, {"args": ["/ovirt-engine/api"], "expected": []}, {"args": ["/ovirt-engine/api/"], "expected": []}, {"args": ["vms/1/start/"], "expected": [{"__tuple__": ["vms", "1"]}, {"__tuple__": ["start", null]}]}, {"args": ["/ovirt-engine/api/datacenters/a/clusters/b/networks"], "expected": [{"__tuple__": ["datacenters", "a"]}, {"__tuple__": ["clusters", "b"]}, {"__tuple__": ["networks", null]}]}, {"args": ["/ovirt-engine/apix/vms/1"], "expected": [{"__tuple__": ["ovirt-engine", "apix"]}, {"__tuple__": ["vms", "1"]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-build-query', 1, 'func', 'Строка запроса списка', 'Соберите строку запроса для коллекции. Функция build_query(search, sortby, page, max_items, follow). Значение параметра search склеивается из частей через один пробел, пустые части пропускаются: сам search (строка), затем "sortby " + sortby (если sortby не пустая строка), затем "page " + номер (если page не None). В значении кодируются только три символа: пробел → %20, = → %3D, * → %2A. Параметры идут в порядке search, max, follow; search включается, только если его значение непусто; max=<число> — если max_items не None (ноль тоже включается); follow=<имена через запятую> — если список follow непуст. Параметры соединяются через &, знак ? в начало не ставьте. Если параметров нет, верните пустую строку.', 'def build_query(search, sortby, page, max_items, follow):
    pass
', 'Сначала соберите список частей и склейте пробелом, потом три replace. Затем список пар name=value через ''&''.', '{"func": "build_query", "tests": [{"args": ["status=up", "name", 2, 10, ["nics", "disk_attachments"]], "expected": "search=status%3Dup%20sortby%20name%20page%202&max=10&follow=nics,disk_attachments"}, {"args": ["", "", null, null, []], "expected": ""}, {"args": ["name=web*", "", null, 5, []], "expected": "search=name%3Dweb%2A&max=5"}, {"args": ["", "", 1, 10, []], "expected": "search=page%201&max=10"}, {"args": ["", "name", null, null, ["nics"]], "expected": "search=sortby%20name&follow=nics"}, {"args": ["", "", null, 0, []], "expected": "max=0"}, {"args": ["a=b and c=d", "", 3, null, []], "expected": "search=a%3Db%20and%20c%3Dd%20page%203"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-minimal-role', 2, 'func', 'Минимальная роль', 'Автоматизации нужна роль с наименьшими правами. Даны roles — словарь имя роли → список операций — и needed — список нужных операций. Напишите функцию minimal_role(roles, needed): верните имя роли, в которой есть все нужные операции, а число различных операций наименьшее; при равенстве — имя, меньшее по алфавиту. Если подходящей роли нет, верните пустую строку. При пустом needed подходит любая роль.', 'def minimal_role(roles, needed):
    pass
', 'Отфильтруйте роли, у которых set(needed) <= set(ops), и возьмите минимум по (len(set(ops)), имя).', '{"func": "minimal_role", "tests": [{"args": [{"UserRole": ["view", "run"], "PowerUserRole": ["view", "run", "create", "edit"], "SuperUser": ["view", "run", "create", "edit", "delete", "admin"], "ReadOnly": ["view"]}, ["view"]], "expected": "ReadOnly"}, {"args": [{"UserRole": ["view", "run"], "PowerUserRole": ["view", "run", "create", "edit"], "SuperUser": ["view", "run", "create", "edit", "delete", "admin"], "ReadOnly": ["view"]}, ["run"]], "expected": "UserRole"}, {"args": [{"UserRole": ["view", "run"], "PowerUserRole": ["view", "run", "create", "edit"], "SuperUser": ["view", "run", "create", "edit", "delete", "admin"], "ReadOnly": ["view"]}, ["create", "view"]], "expected": "PowerUserRole"}, {"args": [{"UserRole": ["view", "run"], "SuperUser": ["view", "run", "delete", "admin"]}, ["admin", "view"]], "expected": "SuperUser"}, {"args": [{"UserRole": ["view", "run"]}, ["boom"]], "expected": ""}, {"args": [{"UserRole": ["view", "run"], "ReadOnly": ["view"]}, []], "expected": "ReadOnly"}, {"args": [{"b": ["x", "y"], "a": ["x", "z"]}, ["x"]], "expected": "a"}, {"args": [{"dup": ["x", "x", "x"], "two": ["x", "y"]}, ["x"]], "expected": "dup"}, {"args": [{}, ["x"]], "expected": ""}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-allowed', 3, 'func', 'Проверка прав с наследованием', 'Права в oVirt наследуются вниз по иерархии. Объекты записаны путями вроде "dc1/cl1/vm1". Дано: grants — словарь путь → список ролей пользователя на этом объекте (ключ "" означает всю систему), roles — словарь роль → список операций. Напишите функцию allowed(grants, roles, path, op): верните True, если на самом объекте path или на любом его предке (по целым сегментам: "dc1" — предок "dc1/cl1", но не "dc10/x") у пользователя есть роль, где есть операция op. Роль, которой нет в roles, не даёт ничего. Права на потомков вверх не действуют.', 'def allowed(grants, roles, path, op):
    pass
', 'Постройте префиксы пути: '''', ''dc1'', ''dc1/cl1'', ... и для каждого загляните в grants.', '{"func": "allowed", "tests": [{"args": [{"dc1": ["UserRole"]}, {"UserRole": ["view", "run"]}, "dc1/cl1/vm1", "run"], "expected": true}, {"args": [{"dc1": ["UserRole"]}, {"UserRole": ["view", "run"]}, "dc1/cl1/vm1", "delete"], "expected": false}, {"args": [{"dc1": ["UserRole"]}, {"UserRole": ["view", "run"]}, "dc10/x", "run"], "expected": false}, {"args": [{"": ["SuperUser"]}, {"SuperUser": ["delete"]}, "dc9/cl2/vm7", "delete"], "expected": true}, {"args": [{"dc1/cl1": ["PowerUserRole"]}, {"PowerUserRole": ["create"]}, "dc1", "create"], "expected": false}, {"args": [{"dc1/cl1": ["PowerUserRole"]}, {"PowerUserRole": ["create"]}, "dc1/cl1/vm1", "create"], "expected": true}, {"args": [{"dc1": ["Ghost"]}, {"UserRole": ["run"]}, "dc1/vm", "run"], "expected": false}, {"args": [{"dc1": ["A", "B"], "dc1/vm": ["C"]}, {"A": ["x"], "B": ["y"], "C": ["z"]}, "dc1/vm", "y"], "expected": true}, {"args": [{"dc1/vm": ["C"]}, {"C": ["z"]}, "dc1/vm", "z"], "expected": true}, {"args": [{}, {}, "", "run"], "expected": false}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-login-times', 4, 'func', 'Когда клиент берёт новый токен', 'Клиент автоматизации обращается к API в моменты request_times (целые секунды по возрастанию). Токен выдаётся на lifetime секунд с момента получения. Правила: на первом запросе клиент получает токен; на каждом следующем запросе в момент t, если t >= t_выдачи + lifetime - skew (запас skew секунд до конца срока), клиент заранее получает новый токен в этот же момент t. Иначе использует прежний. Напишите функцию login_times(request_times, lifetime, skew): верните список моментов, в которые клиент получал токен. Для пустого списка запросов верните пустой список.', 'def login_times(request_times, lifetime, skew):
    pass
', 'Храните момент последней выдачи; на каждом запросе сравнивайте t с issued + lifetime - skew.', '{"func": "login_times", "tests": [{"args": [[0, 10, 20, 30, 40], 25, 5], "expected": [0, 20, 40]}, {"args": [[], 10, 1], "expected": []}, {"args": [[5], 10, 0], "expected": [5]}, {"args": [[0, 9, 10, 11], 10, 0], "expected": [0, 10]}, {"args": [[0, 100], 10, 2], "expected": [0, 100]}, {"args": [[0, 1, 2], 5, 10], "expected": [0, 1, 2]}, {"args": [[0, 5, 9, 14, 19, 24], 10, 2], "expected": [0, 9, 19]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-event-digest', 5, 'func', 'Свежие события из журнала', 'Внешний скрипт опрашивает журнал событий и получает строки вида "2026-10-30 12:00:01 | 42 | WARNING | VM web1 started on host h1": время, числовой идентификатор, важность (NORMAL, WARNING или ERROR) и текст. Строка корректна, если после split(" | ", 3) частей ровно четыре, идентификатор состоит из цифр (после strip) и важность — одна из трёх. Некорректные строки пропускаются. Если идентификатор встречается снова, берётся первая строка. Напишите функцию digest(lines, min_severity): верните кортеж (last_id, alerts). last_id — наибольший идентификатор среди корректных строк любой важности (0, если таких нет). alerts — список кортежей (id, текст) тех корректных строк, чья важность не ниже min_severity (порядок NORMAL < WARNING < ERROR), отсортированный по id. Текст — без пробелов по краям.', 'def digest(lines, min_severity):
    pass
', 'Разбирайте строку в try-блоке или проверками; словарь id → (важность, текст) с условием ''не перезаписывать'' решает дубликаты.', '{"func": "digest", "tests": [{"args": [[], "NORMAL"], "expected": {"__tuple__": [0, []]}}, {"args": [["2026-10-30 12:00:01 | 42 | WARNING | VM web1 started on host h1"], "WARNING"], "expected": {"__tuple__": [42, [{"__tuple__": [42, "VM web1 started on host h1"]}]]}}, {"args": [["t | 1 | NORMAL | ok", "t | 2 | ERROR | host h2 is non responsive", "t | 3 | WARNING | low disk"], "WARNING"], "expected": {"__tuple__": [3, [{"__tuple__": [2, "host h2 is non responsive"]}, {"__tuple__": [3, "low disk"]}]]}}, {"args": [["t | 5 | NORMAL | a", "broken line", "t | x | ERROR | bad id", "t | 6 | FATAL | unknown", "t | 7 | NORMAL"], "NORMAL"], "expected": {"__tuple__": [5, [{"__tuple__": [5, "a"]}]]}}, {"args": [["t | 9 | ERROR | second", "t | 8 | WARNING | first"], "NORMAL"], "expected": {"__tuple__": [9, [{"__tuple__": [8, "first"]}, {"__tuple__": [9, "second"]}]]}}, {"args": [["t | 4 | ERROR | one", "t | 4 | NORMAL | two"], "ERROR"], "expected": {"__tuple__": [4, [{"__tuple__": [4, "one"]}]]}}, {"args": [["t | 4 | ERROR | one", "t | 4 | NORMAL | two"], "NORMAL"], "expected": {"__tuple__": [4, [{"__tuple__": [4, "one"]}]]}}, {"args": [["t | 1 | NORMAL | has | pipe | inside"], "NORMAL"], "expected": {"__tuple__": [1, [{"__tuple__": [1, "has | pipe | inside"]}]]}}, {"args": [["t |  12  | ERROR |  spaced  "], "ERROR"], "expected": {"__tuple__": [12, [{"__tuple__": [12, "spaced"]}]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-user-data', 6, 'func', 'Сборка user-data для cloud-init', 'Напишите функцию build_user_data(hostname, users, packages, runcmd), которая собирает текст user-data в формате YAML. Первая строка всегда "#cloud-config". Далее секции в таком порядке, пустые и None пропускаются: "hostname: <имя>"; "users:", и для каждого пользователя (словарь с полями name и keys) строка "  - name: <имя>", а если список keys непуст — "    ssh_authorized_keys:" и по строке "      - <ключ>" на каждый ключ; "packages:" и строки "  - <пакет>"; "runcmd:" и строки "  - <команда>". Строки соединяются через \n, в конце один \n. Экранировать ничего не нужно.', 'def build_user_data(hostname, users, packages, runcmd):
    pass
', 'Копите список строк и добавляйте секции по очереди; в конце ''\n''.join(lines) + ''\n''.', '{"func": "build_user_data", "tests": [{"args": ["", [], [], []], "expected": "#cloud-config\n"}, {"args": ["web1", [], [], []], "expected": "#cloud-config\nhostname: web1\n"}, {"args": [null, [{"name": "ops", "keys": ["ssh-ed25519 AAA"]}], [], []], "expected": "#cloud-config\nusers:\n  - name: ops\n    ssh_authorized_keys:\n      - ssh-ed25519 AAA\n"}, {"args": ["web1", [{"name": "ops", "keys": []}, {"name": "bob", "keys": ["k1", "k2"]}], ["nginx", "curl"], ["systemctl enable nginx"]], "expected": "#cloud-config\nhostname: web1\nusers:\n  - name: ops\n  - name: bob\n    ssh_authorized_keys:\n      - k1\n      - k2\npackages:\n  - nginx\n  - curl\nruncmd:\n  - systemctl enable nginx\n"}, {"args": ["", [], ["git"], ["echo hi", "touch /ready"]], "expected": "#cloud-config\npackages:\n  - git\nruncmd:\n  - echo hi\n  - touch /ready\n"}, {"args": ["db", [{"name": "root"}], [], []], "expected": "#cloud-config\nhostname: db\nusers:\n  - name: root\n"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-network-config', 7, 'func', 'Сетевая конфигурация для первой загрузки', 'Напишите функцию build_network_config(nics), которая строит сетевую конфигурацию в формате YAML. nics — список словарей с полем name и необязательными ip, netmask (вида "255.255.255.0"), gateway, dns (список). Первая строка "version: 2". Если nics пуст, больше ничего нет. Иначе дальше строка "ethernets:", и для каждого интерфейса в данном порядке: "  <name>:". Если ip задан — "    addresses:" и строка "      - <ip>/<префикс>", где префикс — число единичных битов в маске; затем, если gateway задан, "    gateway4: <gateway>"; затем, если dns непуст, "    nameservers:", "      addresses:" и по строке "        - <dns>" на каждый сервер. Если ip не задан — одна строка "    dhcp4: true" (gateway и dns в этом случае игнорируются). Строки соединяются через \n, в конце один \n.', 'def build_network_config(nics):
    pass
', 'Префикс: sum(bin(int(o)).count(''1'') for o in netmask.split(''.'')). Остальное — аккуратные append в список строк.', '{"func": "build_network_config", "tests": [{"args": [[]], "expected": "version: 2\n"}, {"args": [[{"name": "eth0"}]], "expected": "version: 2\nethernets:\n  eth0:\n    dhcp4: true\n"}, {"args": [[{"name": "eth0", "ip": "10.0.0.21", "netmask": "255.255.255.0"}]], "expected": "version: 2\nethernets:\n  eth0:\n    addresses:\n      - 10.0.0.21/24\n"}, {"args": [[{"name": "eth0", "ip": "10.0.0.21", "netmask": "255.255.255.0", "gateway": "10.0.0.1", "dns": ["10.0.0.2", "10.0.0.3"]}]], "expected": "version: 2\nethernets:\n  eth0:\n    addresses:\n      - 10.0.0.21/24\n    gateway4: 10.0.0.1\n    nameservers:\n      addresses:\n        - 10.0.0.2\n        - 10.0.0.3\n"}, {"args": [[{"name": "eth0", "ip": "172.16.5.9", "netmask": "255.255.252.0"}, {"name": "eth1", "gateway": "1.1.1.1", "dns": ["8.8.8.8"]}]], "expected": "version: 2\nethernets:\n  eth0:\n    addresses:\n      - 172.16.5.9/22\n  eth1:\n    dhcp4: true\n"}, {"args": [[{"name": "ens3", "ip": "192.168.1.5", "netmask": "255.255.255.128", "dns": []}]], "expected": "version: 2\nethernets:\n  ens3:\n    addresses:\n      - 192.168.1.5/25\n"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-pool-plan', 8, 'func', 'План пула машин', 'Пул создаёт машины из шаблона по маске имени pattern. Знаки ''?'' в маске идут одной группой (или их нет совсем): префикс — всё до группы, суффикс — всё после. Имя номера k (k >= 1) — префикс + k, дополненное нулями слева до числа знаков ''?'' (str(k).zfill(width)) + суффикс; если знаков ''?'' нет, суффикс пуст, ширина 1 и номер просто дописывается в конец маски. Участники пула — имена из existing, совпадающие с именем какого-либо номера в точности ("p-1-x" при маске "p-??-x" не участник). Напишите функцию pool_plan(pattern, size, existing, running, prestarted): новые машины создаются, пока участников меньше size, и берут наименьшие свободные номера по возрастанию. Верните кортеж (new_names, to_start). new_names — имена новых машин в порядке создания. Затем возьмите всех участников и новые имена, отсортируйте по имени; первые min(prestarted, size) из них должны работать, и to_start — те из них, которых нет в списке running, в том же порядке.', 'def pool_plan(pattern, size, existing, running, prestarted):
    pass
', 'Сначала функция name(k). Участник: для нескольких k построенное имя равно строке — проще разобрать середину: str(int(mid)).zfill(width) == mid и int(mid) >= 1.', '{"func": "pool_plan", "tests": [{"args": ["web-???", 3, [], [], 0], "expected": {"__tuple__": [["web-001", "web-002", "web-003"], []]}}, {"args": ["web-???", 3, ["web-002"], [], 0], "expected": {"__tuple__": [["web-001", "web-003"], []]}}, {"args": ["web-???", 2, ["web-001", "web-002", "web-003"], [], 0], "expected": {"__tuple__": [[], []]}}, {"args": ["web-???", 3, ["web-001", "other", "db-002"], ["web-001"], 2], "expected": {"__tuple__": [["web-002", "web-003"], ["web-002"]]}}, {"args": ["vm", 3, ["vm2"], [], 5], "expected": {"__tuple__": [["vm1", "vm3"], ["vm1", "vm2", "vm3"]]}}, {"args": ["p-??-x", 2, ["p-01-x", "p-1-x"], ["p-01-x"], 1], "expected": {"__tuple__": [["p-02-x"], []]}}, {"args": ["w-???", 0, [], [], 3], "expected": {"__tuple__": [[], []]}}, {"args": ["a-?", 1, ["a-1", "a-2"], [], 1], "expected": {"__tuple__": [[], ["a-1"]]}}, {"args": ["n-??", 12, [], ["n-03"], 4], "expected": {"__tuple__": [["n-01", "n-02", "n-03", "n-04", "n-05", "n-06", "n-07", "n-08", "n-09", "n-10", "n-11", "n-12"], ["n-01", "n-02", "n-04"]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-search-vms', 9, 'func', 'Язык поиска oVirt', 'Реализуйте упрощённый язык search. Функция search_vms(query, vms): vms — список словарей машин (поле name всегда есть, остальные поля произвольные, например status, cluster, memory). Запрос — термы, соединённые словами and и or (в любом регистре, отдельными словами, окружёнными пробелами); and связывает сильнее, чем or. Терм имеет вид поле оператор значение, оператор — один из =, !=, <, >, вокруг оператора могут быть пробелы, значение не содержит пробелов. Поле, которого нет у машины, делает терм ложным при любом операторе. Для = значение сравнивается со str(поле) без учёта регистра, и символ * в значении означает любую (в том числе пустую) последовательность символов; != — отрицание =, но только для присутствующего поля. Для < и > поле и значение приводятся к int; если не получается — терм ложен. Пустой запрос подходит всем. Верните список имён подходящих машин в исходном порядке.', 'def search_vms(query, vms):
    pass
', 're.split(r''\s+(and|or)\s+'', q, flags=re.I) даёт чередование терм/слово. Разбейте на группы по or, внутри группы — all(and). Для * постройте регулярное выражение из re.escape кусков, склеенных ''.*''.', '{"func": "search_vms", "tests": [{"args": ["name=web*", [{"name": "web1", "status": "up", "cluster": "prod", "memory": 4096}, {"name": "web2", "status": "down", "cluster": "prod", "memory": 2048}, {"name": "db1", "status": "up", "cluster": "prod", "memory": 16384}, {"name": "test1", "status": "up", "cluster": "dev", "memory": 1024}, {"name": "Web3", "status": "up", "cluster": "dev", "memory": 512}]], "expected": ["web1", "web2", "Web3"]}, {"args": ["status=up and cluster=prod", [{"name": "web1", "status": "up", "cluster": "prod", "memory": 4096}, {"name": "web2", "status": "down", "cluster": "prod", "memory": 2048}, {"name": "db1", "status": "up", "cluster": "prod", "memory": 16384}, {"name": "test1", "status": "up", "cluster": "dev", "memory": 1024}, {"name": "Web3", "status": "up", "cluster": "dev", "memory": 512}]], "expected": ["web1", "db1"]}, {"args": ["status=down or cluster=dev", [{"name": "web1", "status": "up", "cluster": "prod", "memory": 4096}, {"name": "web2", "status": "down", "cluster": "prod", "memory": 2048}, {"name": "db1", "status": "up", "cluster": "prod", "memory": 16384}, {"name": "test1", "status": "up", "cluster": "dev", "memory": 1024}, {"name": "Web3", "status": "up", "cluster": "dev", "memory": 512}]], "expected": ["web2", "test1", "Web3"]}, {"args": ["status=up and cluster=dev or name=db1", [{"name": "web1", "status": "up", "cluster": "prod", "memory": 4096}, {"name": "web2", "status": "down", "cluster": "prod", "memory": 2048}, {"name": "db1", "status": "up", "cluster": "prod", "memory": 16384}, {"name": "test1", "status": "up", "cluster": "dev", "memory": 1024}, {"name": "Web3", "status": "up", "cluster": "dev", "memory": 512}]], "expected": ["db1", "test1", "Web3"]}, {"args": ["memory > 3000", [{"name": "web1", "status": "up", "cluster": "prod", "memory": 4096}, {"name": "web2", "status": "down", "cluster": "prod", "memory": 2048}, {"name": "db1", "status": "up", "cluster": "prod", "memory": 16384}, {"name": "test1", "status": "up", "cluster": "dev", "memory": 1024}, {"name": "Web3", "status": "up", "cluster": "dev", "memory": 512}]], "expected": ["web1", "db1"]}, {"args": ["memory<1024", [{"name": "web1", "status": "up", "cluster": "prod", "memory": 4096}, {"name": "Web3", "status": "up", "cluster": "dev", "memory": 512}]], "expected": ["Web3"]}, {"args": ["cluster != prod", [{"name": "web1", "status": "up", "cluster": "prod", "memory": 4096}, {"name": "test1", "status": "up", "cluster": "dev", "memory": 1024}, {"name": "x"}]], "expected": ["test1"]}, {"args": ["", [{"name": "a"}, {"name": "b"}]], "expected": ["a", "b"]}, {"args": ["owner=bob", [{"name": "a"}, {"name": "b", "owner": "Bob"}]], "expected": ["b"]}, {"args": ["owner != bob", [{"name": "a"}, {"name": "b", "owner": "Bob"}, {"name": "c", "owner": "eve"}]], "expected": ["c"]}, {"args": ["name = *1 AND status=UP", [{"name": "web1", "status": "up"}, {"name": "db1", "status": "down"}, {"name": "test1", "status": "Up"}, {"name": "web2", "status": "up"}]], "expected": ["web1", "test1"]}, {"args": ["name=*e*", [{"name": "web1"}, {"name": "db1"}, {"name": "test1"}]], "expected": ["web1", "test1"]}, {"args": ["memory>1 or name=order", [{"name": "order", "memory": "n/a"}, {"name": "x", "memory": "2"}, {"name": "y", "memory": "1"}]], "expected": ["order", "x"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-walk-pages', 10, 'func', 'Обход страниц API', 'Клиент собирает всю коллекцию страницами по max_items элементов. Поддельный сервер задан списком pages: на запрос страницы с номером p (с единицы) он отвечает pages[p-1], а за пределами списка — пустым списком. Клиент запрашивает страницы 1, 2, 3, ... и после каждого ответа добавляет в результат элементы, которых там ещё нет (при сдвиге страниц между запросами элементы могут повториться); останавливается сразу после первого ответа, в котором меньше max_items элементов (пустой ответ тоже такой). Напишите функцию walk_pages(pages, max_items): верните кортеж (items, requests) — список собранных элементов в порядке получения и число сделанных запросов. Повторы считайте в ответе сервера, а не в собранных элементах (длина ответа сравнивается с max_items до удаления повторов).', 'def walk_pages(pages, max_items):
    pass
', 'Цикл while True: запрос, добавление новых, проверка len(chunk) < max_items.', '{"func": "walk_pages", "tests": [{"args": [[[1, 2], [3, 4], [5]], 2], "expected": {"__tuple__": [[1, 2, 3, 4, 5], 3]}}, {"args": [[[1, 2], [3, 4]], 2], "expected": {"__tuple__": [[1, 2, 3, 4], 3]}}, {"args": [[], 2], "expected": {"__tuple__": [[], 1]}}, {"args": [[[1, 2], [3], [4, 5]], 2], "expected": {"__tuple__": [[1, 2, 3], 2]}}, {"args": [[[1, 2, 3]], 5], "expected": {"__tuple__": [[1, 2, 3], 1]}}, {"args": [[[1, 2], [2, 3], [3]], 2], "expected": {"__tuple__": [[1, 2, 3], 3]}}, {"args": [[[1, 2], [2, 1], [1, 2]], 2], "expected": {"__tuple__": [[1, 2], 4]}}, {"args": [[["a"]], 1], "expected": {"__tuple__": [["a"], 2]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-poll-backoff', 11, 'func', 'Ожидание статуса с растущей паузой', 'Скрипт ждёт, пока машина достигнет статуса target, опрашивая API с растущей паузой. Ответы заданы списком statuses: n-й опрос (с нуля) возвращает statuses[n], а после конца списка повторяется последний статус. Модель времени: опрос 0 происходит в момент t = 0. Правила после каждого опроса: если статус равен target — вернуть (''ok'', число_опросов, t); если статус входит в список fail — вернуть (''failed'', число_опросов, t); иначе, если t + delay > deadline — вернуть (''timeout'', число_опросов, t); иначе ждать: t += delay, затем delay = min(delay * factor, cap), и следующий опрос. Первая пауза равна initial. Напишите функцию poll_backoff(statuses, target, fail, initial, factor, cap, deadline) и верните этот кортеж.', 'def poll_backoff(statuses, target, fail, initial, factor, cap, deadline):
    pass
', 'Три переменные: t, delay, polls. Статус опроса — statuses[min(polls, len(statuses) - 1)] до увеличения polls.', '{"func": "poll_backoff", "tests": [{"args": [["WaitForLaunch", "PoweringUp", "Up"], "Up", ["Down"], 1, 2, 30, 60], "expected": {"__tuple__": ["ok", 3, 3]}}, {"args": [["PoweringUp"], "Up", ["Down"], 1, 2, 4, 20], "expected": {"__tuple__": ["timeout", 7, 19]}}, {"args": [["Up"], "Up", [], 1, 2, 4, 20], "expected": {"__tuple__": ["ok", 1, 0]}}, {"args": [["PoweringUp", "Down"], "Up", ["Down"], 1, 2, 4, 20], "expected": {"__tuple__": ["failed", 2, 1]}}, {"args": [["x"], "Up", [], 1, 2, 4, 0], "expected": {"__tuple__": ["timeout", 1, 0]}}, {"args": [["x"], "y", [], 5, 1, 5, 12], "expected": {"__tuple__": ["timeout", 3, 10]}}, {"args": [["a", "a", "a", "Up"], "Up", [], 2, 3, 10, 100], "expected": {"__tuple__": ["ok", 4, 18]}}, {"args": [["a"], "y", [], 5, 1, 5, 10], "expected": {"__tuple__": ["timeout", 3, 10]}}, {"args": [["Up", "Up"], "Down", ["Up"], 1, 2, 4, 10], "expected": {"__tuple__": ["failed", 1, 0]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-plan-vms', 12, 'func', 'План приведения машин к описанию', 'Идемпотентный планировщик, как в модуле ovirt_vm. current — словарь имя машины → "up" или "down" (существующие машины), desired — словарь имя → желаемое состояние: "present", "running", "stopped" или "absent". Правила для имени из desired. present: если машины нет — create (новая машина выключена), иначе ничего. running: нет машины — create, start; выключена — start; включена — ничего. stopped: нет машины — create; включена — stop; выключена — ничего. absent: нет машины — ничего; выключена — remove; включена — stop, remove. Машины из current, которых нет в desired, не трогают. Напишите функцию plan_vms(current, desired): верните список кортежей (имя, действие), порядок — по имени в алфавитном порядке, а для одной машины — в порядке выполнения. Если всё уже соответствует описанию, список пуст.', 'def plan_vms(current, desired):
    pass
', 'Цикл по sorted(desired); внутри — ветки по состоянию, текущее состояние current.get(name) равно None, если машины нет.', '{"func": "plan_vms", "tests": [{"args": [{"a": "up", "b": "down"}, {"a": "running", "b": "running", "c": "running"}], "expected": [{"__tuple__": ["b", "start"]}, {"__tuple__": ["c", "create"]}, {"__tuple__": ["c", "start"]}]}, {"args": [{"a": "up", "b": "down"}, {"a": "stopped", "b": "stopped", "c": "stopped"}], "expected": [{"__tuple__": ["a", "stop"]}, {"__tuple__": ["c", "create"]}]}, {"args": [{"a": "up", "b": "down"}, {"a": "absent", "b": "absent", "c": "absent"}], "expected": [{"__tuple__": ["a", "stop"]}, {"__tuple__": ["a", "remove"]}, {"__tuple__": ["b", "remove"]}]}, {"args": [{"a": "up", "b": "down"}, {"a": "present", "c": "present"}], "expected": [{"__tuple__": ["c", "create"]}]}, {"args": [{"a": "up"}, {"a": "running"}], "expected": []}, {"args": [{"z": "up"}, {}], "expected": []}, {"args": [{}, {"w2": "running", "w1": "present", "w3": "absent"}], "expected": [{"__tuple__": ["w1", "create"]}, {"__tuple__": ["w2", "create"]}, {"__tuple__": ["w2", "start"]}]}, {"args": [{"x": "down", "y": "up"}, {"x": "present", "y": "present"}], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 23, 'ov23-retry-run', 13, 'func', 'Безопасные повторы вызова', 'Смоделируйте вызов API с повторами. Исходы попыток заданы списком outcomes: попытка n (с нуля) даёт outcomes[n], после конца списка повторяется последний. Исходы: "ok" (успех), "bad_request" (ошибка клиента, повтор бессмыслен), "unauthorized" (401: токен истёк), "timeout" (неизвестно, дошёл ли запрос), "conflict" и "server_error" (занято или сбой, запрос не применён); любой другой исход — неудача. Правила после попытки с исходом не "ok": если исход "bad_request" или неизвестный — неудача; если сделано max_attempts попыток — неудача; "unauthorized": получаем новый токен и повторяем сразу без паузы, но один раз за вызов (вторая 401 — неудача); "timeout": при idempotent=False неудача (запрос мог примениться), иначе — повтор с паузой; "conflict" и "server_error" — повтор с паузой. Пауза с номером i (с нуля среди пауз) равна min(base * 2**i, cap). Напишите функцию run_with_retries(outcomes, idempotent, max_attempts, base, cap) и верните кортеж (статус, число_попыток, суммарная_пауза), где статус — "ok" или "failed".', 'def run_with_retries(outcomes, idempotent, max_attempts, base, cap):
    pass
', 'Счётчики: attempts, waits (число пауз), total, флаг renewed. Порядок проверок: ok, bad/unknown, лимит попыток, unauthorized, timeout, пауза.', '{"func": "run_with_retries", "tests": [{"args": [["ok"], true, 3, 1, 8], "expected": {"__tuple__": ["ok", 1, 0]}}, {"args": [["server_error", "server_error", "ok"], true, 5, 1, 8], "expected": {"__tuple__": ["ok", 3, 3]}}, {"args": [["server_error"], true, 4, 1, 4], "expected": {"__tuple__": ["failed", 4, 7]}}, {"args": [["timeout", "ok"], false, 3, 1, 8], "expected": {"__tuple__": ["failed", 1, 0]}}, {"args": [["timeout", "ok"], true, 3, 1, 8], "expected": {"__tuple__": ["ok", 2, 1]}}, {"args": [["bad_request", "ok"], true, 3, 1, 8], "expected": {"__tuple__": ["failed", 1, 0]}}, {"args": [["unauthorized", "ok"], false, 3, 1, 8], "expected": {"__tuple__": ["ok", 2, 0]}}, {"args": [["unauthorized", "unauthorized", "ok"], true, 5, 1, 8], "expected": {"__tuple__": ["failed", 2, 0]}}, {"args": [["conflict", "unauthorized", "ok"], false, 5, 2, 3], "expected": {"__tuple__": ["ok", 3, 2]}}, {"args": [["weird"], true, 3, 1, 8], "expected": {"__tuple__": ["failed", 1, 0]}}, {"args": [["unauthorized"], true, 1, 1, 1], "expected": {"__tuple__": ["failed", 1, 0]}}, {"args": [["conflict", "conflict", "conflict", "ok"], true, 4, 1, 100], "expected": {"__tuple__": ["ok", 4, 7]}}]}');
